module bracket_sequence(\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] string_bits,\n    output reg [15:0] result,\n    output reg done\n);\n    // States\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COUNT_OPEN_CLOSE = 3'd1;\n    localparam [2:0] CHECK_COUNTS = 3'd2;\n    localparam [2:0] COMPUTE_COST = 3'd3;\n    localparam [2:0] DONE_STATE = 3'd4;\n    \n    reg [2:0] state;\n    reg [3:0] i;\n    reg [4:0] open_count, close_count;\n    reg signed [5:0] balance;\n    reg in_segment;\n    reg [3:0] start_reg;\n    reg [4:0] cost;\n    \n    wire signed [5:0] balance_next = string_bits[i] ? (balance + 1) : (balance - 1);\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            i <= 4'd0;\n            open_count <= 5'd0;\n            close_count <= 5'd0;\n            balance <= 6'd0;\n            in_segment <= 1'b0;\n            start_reg <= 4'd0;\n            cost <= 5'd0;\n            result <= 16'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COUNT_OPEN_CLOSE;\n                        i <= 4'd0;\n                        open_count <= 5'd0;\n                        close_count <= 5'd0;\n                    end\n                end\n                \n                COUNT_OPEN_CLOSE: begin\n                    if (string_bits[i])\n                        open_count <= open_count + 1'b1;\n                    else\n                        close_count <= close_count + 1'b1;\n                    \n                    if (i == 4'd15)\n                        state <= CHECK_COUNTS;\n                    else\n                        i <= i + 1'b1;\n                end\n                \n                CHECK_COUNTS: begin\n                    if (open_count != close_count) begin\n                        result <= 16'hFFFF;\n                        state <= DONE_STATE;\n                    end else begin\n                        state <= COMPUTE_COST;\n                        i <= 4'd0;\n                        balance <= 6'd0;\n                        in_segment <= 1'b0;\n                        start_reg <= 4'd0;\n                        cost <= 5'd0;\n                    end\n                end\n                \n                COMPUTE_COST: begin\n                    balance <= balance_next;\n                    \n                    if (balance_next < 0 && !in_segment) begin\n                        in_segment <= 1'b1;\n                        start_reg <= i;\n                    end\n                    \n                    if (balance_next == 0 && in_segment) begin\n                        cost <= cost + (i - start_reg + 1);\n                        in_segment <= 1'b0;\n                    end\n                    \n                    if (i == 4'd15) begin\n                        state <= DONE_STATE;\n                        result <= cost;\n                    end else begin\n                        i <= i + 1'b1;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule